mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.TERM TERM, A.PFLSH PFLSH, A.CREDIT_AMT/100000000 creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, A.HAP_CREDIT_AMT as hapCreditAmt, A.CREDIT_FLAG as creditFlag, C.ASSETPOOL_NAME as customerName FROM CREDIT_LINES A
left join CREDIT_ASSETPOOL C on A.CUSTOMER_ID=C.SEQNO
A.CREDIT_TYPE = '03'
AND A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND to_char(A.VDATE,'yyyy-MM-dd') > = #{vdate,jdbcType=DATE}
AND to_char(A.VDATE,'yyyy-MM-dd') < = #{mdate,jdbcType=DATE}

mapper.delete:
delete from CREDIT_ASSETPOOL
where SEQNO in (
select CUSTOMER_ID from CREDIT_LINES where SEQNO = #{seqno,jdbcType=VARCHAR}
)

mapper.select:
       SELECT
	 	A.*
	 FROM 
	 	CREDIT_ASSETPOOL A
       	INNER JOIN CREDIT_LINES B ON A.SEQNO = B.CUSTOMER_ID AND to_char(B.VDATE,'yyyy-MM-dd') = #{vdate}
        where A.ASSETPOOL_NAME = #{customerName,jdbcType=VARCHAR}
